const nodeVideoIDs = `-- name: NodeVideoIDs :many
SELECT id FROM canvas_nodes
WHERE tenant_id = $1
  AND workspace_id IS NOT DISTINCT FROM $2::varchar
  AND deleted_at = 0
  AND project_id = $3
  AND canvas_id = $4
  AND type = $5
ORDER BY storyboard_rank, id
`

type NodeVideoIDsParams struct {
	TenantID    string
	WorkspaceID *string
	ProjectID   string
	CanvasID    string
	Type        int16
}

func (q *Queries) NodeVideoIDs(ctx context.Context, arg NodeVideoIDsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, nodeVideoIDs,
		arg.TenantID,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.CanvasID,
		arg.Type,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nodeVideoNodesLocked = `-- name: NodeVideoNodesLocked :many
SELECT id, tenant_id, workspace_id, project_id, canvas_id, type, storyboard_rank, asset_id, resource_asset_id, revision, active_task_run_id, selected_output_id, selected_asset_id, created_by, updated_by, created_at, updated_at, deleted_at, resource_id, node_data FROM canvas_nodes
WHERE tenant_id = $1
  AND workspace_id IS NOT DISTINCT FROM $2::varchar
  AND deleted_at = 0
  AND project_id = $3
  AND canvas_id = $4
  AND type = $5
ORDER BY storyboard_rank, id
FOR UPDATE
`

type NodeVideoNodesLockedParams struct {
	TenantID    string
	WorkspaceID *string
	ProjectID   string
	CanvasID    string
	Type        int16
}

func (q *Queries) NodeVideoNodesLocked(ctx context.Context, arg NodeVideoNodesLockedParams) ([]CanvasNode, error) {
	rows, err := q.db.Query(ctx, nodeVideoNodesLocked,
		arg.TenantID,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.CanvasID,
		arg.Type,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CanvasNode{}
	for rows.Next() {
		var i CanvasNode
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.WorkspaceID,
			&i.ProjectID,
			&i.CanvasID,
			&i.Type,
			&i.StoryboardRank,
			&i.AssetID,
			&i.ResourceAssetID,
			&i.Revision,
			&i.ActiveTaskRunID,
			&i.SelectedOutputID,
			&i.SelectedAssetID,
			&i.CreatedBy,
			&i.UpdatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.ResourceID,
			&i.NodeData,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
